  KEY `idx_activity_ip` (`ip_address`),
  KEY `idx_activity_request` (`request_id`),
  KEY `idx_activity_category_result_time` (`category`,`result`,`created_at`),
  KEY `idx_activity_trace` (`trace_id`,`operation_id`),
  CONSTRAINT `fk_activity_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
