INSERT INTO `service_catalog` VALUES (1,'خرابی یا کندی رایانه','IT-COMPUTER','کندی، هنگ کردن یا خطای عملکرد رایانه.','it','urgent',NULL,1,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(2,'رایانه روشن نمی‌شود','IT-BOOT','عدم روشن شدن یا بوت نشدن سیستم.','it','urgent',NULL,1,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(3,'صفحه آبی یا ری‌استارت مکرر','IT-BLUE','خطای صفحه آبی، ری‌استارت یا خاموشی ناگهانی.','it','urgent',NULL,1,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(4,'خرابی قطعه سخت‌افزاری','IT-HARDWARE','مشکوک به خرابی هارد، RAM، پاور یا مادربرد.','it','urgent',NULL,1,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(5,'نصب یا بازیابی ویندوز','IT-PROFILE','نصب مجدد یا بازیابی سیستم‌عامل.','it','normal',NULL,8,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(6,'نصب درایور تجهیزات','IT-DRIVER','نصب درایور پرینتر، اسکنر یا سایر تجهیزات.','it','normal',NULL,8,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(7,'نصب نرم‌افزار سازمانی','IT-SOFTWARE','نصب نرم‌افزارهای مورد تأیید سازمان.','it','normal',NULL,2,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(8,'خطای نرم‌افزار نصب‌شده','IT-SOFT-ERROR','خطا، بسته شدن یا کار نکردن نرم‌افزار.','it','normal',NULL,2,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(9,'مشکل پرینتر یا اسکنر','IT-PRINTER','چاپ نکردن، خطای چاپ یا اسکن.','it','normal',NULL,5,1,0,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(10,'کیبورد، ماوس و مانیتور','IT-PERIPHERAL','خرابی یا تعویض تجهیزات جانبی.','it','normal',NULL,6,1,0,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(11,'اختلال شبکه یا اینترنت','IT-NET','قطعی، کندی یا خطای اتصال شبکه و اینترنت.','it','urgent',NULL,3,1,1,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(12,'اشتراک فایل و پرینتر شبکه','IT-SHARE','دسترسی به فایل یا پرینتر اشتراکی.','it','normal',NULL,3,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(13,'حساب کاربری و رمز عبور','IT-ACCOUNT','ساخت حساب، تغییر یا بازیابی رمز.','it','normal',NULL,4,1,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(14,'دسترسی به سامانه داخلی','IT-ACCESS','دسترسی یا اصلاح سطح دسترسی سامانه‌ها.','it','normal',NULL,4,1,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(15,'پست الکترونیک سازمانی','IT-EMAIL','ساخت، بازیابی یا خطای ایمیل سازمانی.','it','normal',NULL,4,1,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(16,'بازیابی فایل یا پشتیبان‌گیری','IT-BACKUP','بازیابی اطلاعات پاک‌شده یا پشتیبان‌گیری.','it','urgent',NULL,7,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(17,'نصب و راه‌اندازی رایانه جدید','IT-INSTALL-PC','تحویل و راه‌اندازی سیستم جدید.','it','normal',NULL,8,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(18,'جابه‌جایی رایانه','IT-MOVE','انتقال سیستم یا تغییر محل استقرار.','it','normal',NULL,6,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(19,'ثبت یا اصلاح شناسنامه فنی','IT-INVENTORY','تکمیل شناسنامه و مشخصات فنی سیستم.','it','normal',NULL,8,1,1,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(20,'سایر خدمات فناوری اطلاعات','IT-OTHER','موارد دیگر مرتبط با فناوری اطلاعات.','it','normal',NULL,9,1,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(21,'تجهیزات و فضای اداری','SUP-OFFICE','رسیدگی به تجهیزات عمومی یا فضای کار.','support','normal',NULL,10,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(22,'برق و تأسیسات','SUP-ELEC','خرابی برق، پریز، روشنایی یا تأسیسات.','support','normal',NULL,11,2,0,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(23,'سرمایش و گرمایش','SUP-COOLING','خرابی کولر، اسپلیت یا سیستم گرمایش.','support','normal',NULL,11,2,0,'incident',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(24,'اثاثیه و مبلمان اداری','SUP-FURN','تعمیر یا جابه‌جایی میز و صندلی.','support','normal',NULL,12,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(25,'نظافت و خدمات','SUP-CLEAN','درخواست نظافت یا خدمات عمومی.','support','normal',NULL,13,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(26,'لوازم‌التحریر و ملزومات','SUP-STATIONERY','درخواست لوازم‌التحریر و ملزومات اداری.','support','normal',NULL,14,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(27,'اصلاح یا تأیید رکورد رسانه','SUP-CDDVD','درخواست اصلاح رکورد CD/DVD.','support','normal',NULL,15,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(28,'خدمات عمومی سازمان','SUP-GENERAL','سایر خدمات عمومی داخلی سازمان.','support','normal',NULL,15,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29'),(29,'سایر خدمات پشتیبانی','SUP-OTHER','موارد دیگر مرتبط با پشتیبانی.','support','normal',NULL,16,2,0,'request',1,1,'2026-11-04 20:26:29','2026-11-04 20:26:29');
